        return self.render()

    @property
    def _css(self):
        # Group lists by media type and merge all lists at once for each type
        # to avoid creating false ordering constraints from intermediate results
        css = {}
        lists_by_medium = {}

        for css_dict in self._css_lists:
            if css_dict:
                for medium, css_list in css_dict.items():
                    if medium not in lists_by_medium:
                        lists_by_medium[medium] = []
                    if css_list:
                        lists_by_medium[medium].append(css_list)

        for medium, css_lists in lists_by_medium.items():
            if not css_lists:
                css[medium] = []
            elif len(css_lists) == 1:
                # For a single list, deduplicate while preserving the original type
                css[medium] = self._deduplicate(css_lists[0])
            else:
                # Use merge_many to handle merging and deduplication consistently
                css[medium] = self.merge_many(*css_lists)

        return css

    @property
    def _js(self):
        # Collect non-empty lists and merge all at once to avoid creating
        # false ordering constraints from intermediate results.
        lists = [x for x in self._js_lists if x]
        if not lists:
            return []
        if len(lists) == 1:
            # For a single list, deduplicate while preserving the original type
            return self._deduplicate(lists[0])
        return self.merge_many(*lists)

